const fs = require("fs");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const esm = `
import dc from "node:diagnostics_channel";
import { generateText } from "ai";
let spans = 0;
dc.tracingChannel("ai:telemetry").subscribe({ start() { spans++; }, end() {}, asyncStart() {}, asyncEnd() {}, error() {} });
const span = new Proxy({}, { get: (t, p) => (p === "then" ? undefined : () => span) });
const tracer = {
  startActiveSpan(...args) { spans++; return args[args.length - 1](span); },
  startSpan() { spans++; return span; },
};
let modelCalls = 0;
const model = {
  specificationVersion: "v3", provider: "mock", modelId: "mock", supportedUrls: {},
  doGenerate: async () => { modelCalls++; throw new Error("MOCK_MODEL_ERROR"); },
  doStream: async () => { modelCalls++; throw new Error("MOCK_MODEL_ERROR"); },
};
async function count(telemetry) {
  spans = 0; modelCalls = 0;
  try { await generateText({ model, prompt: "hi", maxRetries: 0, experimental_telemetry: telemetry }); } catch (e) {}
  return { spans, modelCalls };
}
const enabled = await count({ isEnabled: true, functionId: "t", tracer });
const unset = await count({ functionId: "t", tracer });
console.log(JSON.stringify({ enabled, unset }));
`;
fs.writeFileSync("/w/t.mjs", esm);
const { execFileSync } = require("child_process");
let out;
try { out = execFileSync(process.execPath, ["/w/t.mjs"], { encoding: "utf8", timeout: 60000 }); }
catch (e) { broken("running generateText failed: " + String(e.stderr || e.message).slice(0, 300)); }
let r;
try { r = JSON.parse(out.trim().split("\n").pop()); } catch (e) { broken("unexpected output: " + out.slice(0, 300)); }
if (r.enabled.modelCalls < 1 || r.unset.modelCalls < 1) broken("the mock model was not called: " + JSON.stringify(r));
if (r.enabled.spans < 1) broken("no telemetry spans seen even with isEnabled: true: " + JSON.stringify(r));
if (r.unset.spans < 1) symptom("generateText recorded no telemetry spans when isEnabled was not set");
console.log("OK: generateText records telemetry spans when isEnabled is not set");

